/* Quizzes 1 a 26 (primer cuatrimestre: unidades 1 y 2). */
QZ(1, 1, "Introducción al lenguaje", [
  VF("Tanto en los lenguajes naturales como formales, la sintaxis no depende del contexto.", true),
  MT("Dado el siguiente programa en C, emparejar según corresponda:<pre class=\"qpre\">#include &lt;stdio.h&gt;\nmain(void)\n{ int A;\n  printf(\"Introducir un nro. entero: \");\n  scanf(\"%d\", &amp;A);\n  printf(\"La mitad de %d es %d\", A, A%2); }</pre>", [["En la compilación", "No se producirá ningún error."], ["En la ejecución", "Se producirá un error pragmático"]], ["No se producirá ningún error.", "Se producirá un error léxico", "Se producirá un error sintáctico", "Se producirá un error semántico", "Se producirá un error pragmático"], "Compila bien, pero A%2 calcula el resto y no la mitad: el programa no cumple su propósito."),
  VF("Los símbolos son signos que dan indicios de alguna entidad o hecho.", false, "Eso describe a los índices."),
  MT("Dado el siguiente programa en lenguaje C, con posibles errores, emparejar según corresponda al tipo de error:<pre class=\"qpre\">Línea 1:  include &lt;stdio.h&gt;\nLínea 2:  main(void)\nLínea 3:  { A int;\nLínea 4:    print(\"Introducir un nro. entero: \");\nLínea 5:    scanf(\"%f\", &amp;A);\nLínea 6:    printf(\"El doble de %d es %d\", A, A*2); }</pre>", [["Línea 1", "Léxico"], ["Línea 2", "Sin error"], ["Línea 3", "Sintáctico"], ["Línea 4", "Léxico"], ["Línea 5", "Semántico"], ["Línea 6", "Sin error"]], ["Léxico", "Sintáctico", "Semántico", "Pragmático", "Sin error"]),
  MT("Empareje cada concepto con el tipo de lenguaje que corresponda.", [["Se formaliza antes de usar", "Lenguaje Formal"], ["Lengua de señas", "Lenguaje Natural"], ["No es ambiguo", "Lenguaje Formal"], ["Programación de computadoras", "Lenguaje Formal"], ["De dominio general", "Lenguaje Natural"], ["Es ambiguo", "Lenguaje Natural"]], ["Lenguaje Formal", "Lenguaje Natural"]),
  VF("En un lenguaje natural una misma frase puede tener distintos significados según el contexto donde se la use.", true),
  VF("En un lenguaje natural dos frases con el mismo significado pueden tener asociadas distintas acciones, dependiendo del lugar donde se las usa.", true),
  MT("Teniendo en cuenta las características de los niveles de complejidad de los lenguajes formales, emparejar según corresponda.", [["PRAGMÁTICO", "DEPENDIENTE DEL CONTEXTO"], ["SINTÁCTICO", "INDEPENDIENTE DEL CONTEXTO"], ["SEMÁNTICO", "DEPENDIENTE DEL CONTEXTO"], ["LÉXICO", "INDEPENDIENTE DEL CONTEXTO"]]),
  VF("En los lenguajes formales un componente léxico puede tener distintos significados según el rol que cumpla en una sentencia.", false),
  MT("Dada la definición de SIGNO, empareje según corresponda.", [["ÍCONO", "Se asemeja a lo que representa."], ["ÍNDICE", "Manifiesta algún fenómeno natural o cultural."], ["SÍMBOLO", "Su relación con lo que representa es una convención."]], null, "En el intento la opción del símbolo quedó mal elegida y la revisión no la muestra: la redacción de esa opción es nuestra.")
]);

QZ(2, 1, "Palabras y lenguajes", [
  VF("El lenguaje que contiene solo la palabra vacía es el elemento neutro de la intersección de lenguajes.", false, "La intersección da el lenguaje con las palabras comunes a los operandos."),
  MT("Dadas las siguientes operaciones con potencias de palabras, establezca cuáles serían sus resultados.", [["u^1", "u"], ["λ^0", "λ"], ["u^0", "λ"], ["λ^2", "λ"]], ["u", "λ", "uu", "λλ"]),
  VF("La palabra vacía λ («lambda») no pertenece a ningún alfabeto.", true),
  VF("Si un lenguaje contiene la palabra vacía, las operaciones estrella positiva y de Kleene son iguales.", true, "La estrella de Kleene contiene todas las potencias de un lenguaje, incluida la potencia cero; la positiva solo las potencias positivas."),
  VF("La estrella de Kleene del lenguaje vacío es igual al lenguaje que contiene solo la palabra vacía.", true, "La potencia cero de cualquier lenguaje, incluido el vacío, es el lenguaje que contiene solo la palabra vacía."),
  VF("Es lo mismo el lenguaje vacío que el lenguaje que contiene solamente la palabra vacía.", false, "El lenguaje vacío no contiene palabra alguna."),
  FL("Una palabra, número o frase que se lee igual hacia adelante que hacia atrás se denomina…", [{ k: "Respuesta", a: ["palíndromo", "palindromo", "palíndroma", "capicúa"] }]),
  VF("Un lenguaje es un conjunto de símbolos y metasímbolos que permiten generar una frase.", false, "Un lenguaje formal es un conjunto de palabras sobre un alfabeto."),
  VF("El lenguaje vacío es el elemento neutro del producto de lenguajes.", false, "El lenguaje vacío es análogo al cero en la matemática de números."),
  XX("Dadas las operaciones Estrella de Kleene y Estrella Positiva, decir cuál/es afirmaciones son ciertas siempre:", ["L^0 no está incluido en L^+", "L^* contiene la palabra vacía", "Φ^+ = Φ"], [1, 2]),
  VF("Dado el lenguaje L1 = {0, 10}, si aplicamos la estrella de Kleene (L1*), el lenguaje que se genera está formado por todas las secuencias de 0 y 1 que terminan en 0 y que no tienen 1 consecutivos. Incluye además la palabra vacía.", true),
  VF("Un alfabeto es un conjunto finito no vacío de símbolos diferentes.", true, "El concepto de alfabeto es la base de la Lingüística Matemática."),
  VF("La ESTRELLA POSITIVA de un lenguaje es una función con dominio y rango en 2^{ß*} (siendo ß el alfabeto), tal que, dado el lenguaje L1, la operación «L1 estrella positiva» da como resultado otro lenguaje L3 formado por todas las potencias de base L1 y exponente i, desde i = 1 hasta infinito.", true),
  VF("La inversa de la estrella positiva de un lenguaje no es igual a la estrella positiva de la inversa.", false, "Son iguales.")
]);

QZ(3, 1, "Gramática y Jerarquía de Chomsky", [
  XX("Según la Jerarquía de Chomsky, una gramática estructurada por frases cuyas reglas de producción tienen la parte izquierda unitaria puede ser de tipo:", ["TIPO 3 o Regular", "TIPO 2 o Independiente del Contexto", "TIPO 1 o Dependiente del Contexto", "TIPO 0 o Irrestricta"], [0, 1]),
  VF("Una SENTENCIA puede tener terminales y no terminales de una gramática.", false, "La secuencia final que se obtiene a partir del axioma contiene solo símbolos terminales."),
  VF("Según la JERARQUÍA DE CHOMSKY, una gramática regular puede generar lenguajes de tipo superior (independientes o dependientes del contexto).", false, "Las gramáticas regulares solo pueden generar lenguajes regulares."),
  MT("Dada la siguiente gramática:<pre class=\"qpre\">S → UVX        bV → Vb\nZX → VbX       YX → VaX\nYb → bY        Ya → aY\nZb → bZ        Za → aZ\nX → λ          aV → Va\nUV → bUZ | aUY | λ</pre>podemos decir que es de … y que genera palabras con el patrón …, donde w es una secuencia cualquiera sobre el alfabeto {a, b}.", [["Tipo:", "TIPO 0 o Irrestricta", ["TIPO 0 o Irrestricta", "TIPO 1 o Dependiente del Contexto", "TIPO 2 o Independiente del Contexto", "TIPO 3 o Regular"]], ["Patrón:", "w.w", ["w.w", "w.w^{-1}", "w^n", "w.w.w"]]], null, "Las gramáticas TIPO 0 o Irrestrictas responden a la definición general de gramática (hay reglas compresoras, como X → λ fuera del axioma)."),
  VF("Según la JERARQUÍA DE CHOMSKY, una gramática de tipo 1 puede generar lenguajes de tipo 2 y 3.", true),
  MT("Dada la gramática estructurada por frases S → aaS | Aac ; A → abA | c, indicar a qué tipo pertenece y qué lenguaje genera.", [["Tipo:", "TIPO 2 o Independiente del Contexto", ["TIPO 3 o Regular", "TIPO 2 o Independiente del Contexto", "TIPO 1 o Dependiente del Contexto", "TIPO 0 o Irrestricta"]], ["Lenguaje:", "(aa)*.(ab)*.c.a.c", ["(aa)*.(ab)*.c.a.c", "(aa)*.c.(ab)*.a.c", "(aa)^+.(ab)*.c", "a^n.(ab)^n.c.a.c"]]], null, "Cuando hay reglas regulares por derecha y por izquierda en una misma gramática se trata de una gramática de tipo 2, aunque genere un lenguaje regular."),
  XX("¿De qué formas se puede describir un lenguaje formal en general?", ["Por comprensión", "Con patrones", "Con operaciones de conjuntos", "Con álgebra de Boole", "Con proposiciones lógicas", "Con todas las formas enunciadas", "Por extensión", "Con gramáticas", "Con ninguna de las formas enunciadas"], [0, 1, 6, 7]),
  MT("Dada la gramática estructurada por frases G = ⟨Σ_{N}, Σ_{T}, P, S⟩ con Σ_{N} = {S, A, B}, Σ_{T} = {a, b, c} y P: S → aA | bB | λ ; A → cA | a ; B → cB | b.<br>Lenguaje 1: {a}.{c}*.{a} ∪ {b}.{c}*.{b} ∪ {λ}<br>Lenguaje 2: {a}*.{c}.{a} ∪ {b}*.{c}.{b} ∪ {λ}<br>Lenguaje 3: {a}*.{c}.{a} ∪ {b}*.{c}.{b}<br>Lenguaje 4: {a}.{c}*.{a} ∪ {b}.{c}*.{b}", [["Indicar a qué tipo pertenece:", "TIPO 3 o Regular", ["TIPO 3 o Regular", "TIPO 2 o Independiente del Contexto", "TIPO 1 o Dependiente del Contexto", "TIPO 0 o Irrestricta"]], ["Seleccione el lenguaje que genera:", "Lenguaje 1", ["Lenguaje 1", "Lenguaje 2", "Lenguaje 3", "Lenguaje 4"]]]),
  MT("Definición formal de una GRAMÁTICA estructurada por frases: G = ⟨Σ_{N}, Σ_{T}, P, S⟩, Σ = Σ_{N} ∪ Σ_{T}. Σ_{N} es el alfabeto de símbolos … o variables; Σ_{T} es el alfabeto de símbolos … de la gramática, que coincide con los símbolos del … que genera; P es el conjunto finito no vacío de … de producción de la forma α → β, donde α = …, con α_{i} y β pertenecientes a … y N perteneciente a …; S es el símbolo … o axioma, que pertenece a …", [["Σ_{N}: símbolos…", "no terminales", ["no terminales", "terminales", "auxiliares"]], ["Σ_{T}: símbolos…", "terminales", ["no terminales", "terminales", "auxiliares"]], ["coincide con los símbolos del…", "lenguaje", ["lenguaje", "axioma", "alfabeto auxiliar"]], ["P es el conjunto de…", "reglas", ["reglas", "palabras", "símbolos"]], ["α =", "α1.N.α2", ["α1.N.α2", "N", "α1.α2"]], ["α_{i} y β pertenecen a…", "Σ*", ["Σ*", "Σ_{T}*", "Σ_{N}"]], ["N pertenece a…", "Σ_{N}", ["Σ_{N}", "Σ_{T}", "Σ*"]], ["S es el símbolo…", "inicial", ["inicial", "final", "terminal"]], ["S pertenece a…", "Σ_{N}", ["Σ_{N}", "Σ_{T}", "Σ*"]]], null, "Definición formal de gramática para estructuras de frases."),
  VF("Una Forma Sentencial es una secuencia de terminales y no terminales que se deriva del axioma de una Gramática para Estructuras de Frases.", true, "Durante la generación de una palabra se obtienen secuencias de símbolos llamadas formas sentenciales."),
  MT("Según la Jerarquía de Chomsky, se puede establecer la siguiente relación entre los tipos de gramáticas, la complejidad de los lenguajes que son capaces de generar y los modelos matemáticos que resuelven el reconocimiento de dichos lenguajes.", [["Tipo 0 o Irrestricta · nivel", "Pragmático", ["Léxico", "Sintáctico", "Semántico", "Pragmático"]], ["Tipo 0 · modelo", "Máquina de Turing", ["Autómata Finito", "Autómata de Pila", "Autómata con Limitación Lineal", "Máquina de Turing"]], ["Tipo 1 o Dependiente del Contexto · nivel", "Semántico", ["Léxico", "Sintáctico", "Semántico", "Pragmático"]], ["Tipo 1 · modelo", "Autómata con Limitación Lineal", ["Autómata Finito", "Autómata de Pila", "Autómata con Limitación Lineal", "Máquina de Turing"]], ["Tipo 2 o Libre de Contexto · nivel", "Sintáctico", ["Léxico", "Sintáctico", "Semántico", "Pragmático"]], ["Tipo 2 · modelo", "Autómata de Pila", ["Autómata Finito", "Autómata de Pila", "Autómata con Limitación Lineal", "Máquina de Turing"]], ["Tipo 3 o Regular · nivel", "Léxico", ["Léxico", "Sintáctico", "Semántico", "Pragmático"]], ["Tipo 3 · modelo", "Autómata Finito", ["Autómata Finito", "Autómata de Pila", "Autómata con Limitación Lineal", "Máquina de Turing"]]]),
  VF("Hay una correspondencia biunívoca entre el conjunto de gramáticas y el conjunto de lenguajes.", false, "Un lenguaje puede tener varias gramáticas que lo generen."),
  VF("Según el lingüista Noam Chomsky existen solo dos tipos de gramáticas: regulares y no regulares.", false, "La jerarquía de Chomsky admite 4 tipos de gramáticas para estructuras de frases."),
  MC("Según la Jerarquía de Chomsky, una gramática estructurada por frases cuyas reglas de producción tienen contexto no vacío en su parte izquierda y se restringe la longitud de su parte derecha, la cual no puede ser menor que la de la parte izquierda, es de tipo:", ["TIPO 2 o Independiente del Contexto", "TIPO 0 o Irrestricta", "TIPO 3 o Regular", "TIPO 1 o Dependiente del Contexto"], 3),
  MT("Dada la siguiente gramática estructurada por frases: G = ⟨Σ_{N}, Σ_{T}, P, S⟩, Σ_{N} = {S, X, Y, Z}, Σ_{T} = {a, b, c}, P: S → X ; YZ → ZY ; Y → c ; X → aXZY | abY ; bZ → bb.", [["Indicar a qué tipo pertenece:", "TIPO 1 o Dependiente del Contexto", ["TIPO 0 o Irrestricta", "TIPO 1 o Dependiente del Contexto", "TIPO 2 o Independiente del Contexto", "TIPO 3 o Regular"]], ["L(G) = {a^n.b^k.c^m} con n, k, m ≥ 1 y…", "n = k = m", ["n = k = m", "n = k", "k = m", "n &gt; k"]]])
]);

QZ(4, 1, "Operaciones con palabras y lenguajes", [
  VF("La palabra vacía λ («lambda») no pertenece a ningún alfabeto.", true),
  XX("Dadas las definiciones de las operaciones Estrella de Kleene y Estrella Positiva, seleccionar la o las opciones correctas.", ["L* = {λ} ∪ L^+", "(L*)^{-1} = (L^{-1})*", "L* = L^0 ∪ L^+", "Φ* = Φ", "Φ* = {λ}", "L^+ = L* − {λ}", "(L^+)^{-1} ≠ (L^{-1})^+", "L* = L^+ cuando el lenguaje L no contiene la palabra vacía."], [0, 1, 2, 4]),
  XX("Dadas las operaciones Estrella de Kleene y Estrella Positiva, decir cuál/es afirmaciones son ciertas siempre:", ["Φ^+ = Φ", "L* contiene la palabra vacía", "L^0 no está incluido en L^+"], [0, 1]),
  VF("Dados los lenguajes L1 y L2, si la cardinalidad de L1 es mayor que la de L2, entonces siempre se cumple que la cardinalidad de L1* es mayor que la de L2*.", false),
  MT("Dadas las siguientes operaciones con potencias de palabras, establezca cuáles serían sus resultados.", [["λ^2", "λ"], ["λ^0", "λ"], ["u^1", "u"], ["u^0", "λ"]], ["u", "λ", "uu", "λλ"]),
  VF("El lenguaje vacío es el elemento neutro del producto de lenguajes.", false),
  VF("El lenguaje que contiene solo la palabra vacía es el elemento neutro de la intersección de lenguajes.", false),
  VF("Dado el lenguaje L1 = {0, 10}, si aplicamos la estrella de Kleene (L1*), el lenguaje que se genera está formado por todas las secuencias de 0 y 1 que terminan en 0 y que no tienen 1 consecutivos. Incluye además la palabra vacía.", true),
  XX("Sean x = caaba, y = ca, dos palabras sobre el alfabeto Σ = {a, b, c}. Indicar cuál/es de las operaciones siguientes da un resultado palíndromo.", ["(y^{-1})^2", "x . y^{-1}", "(x^{-1})^2 . x^2", "(x^2)^{-1}"], [1, 2], "x.y^{-1} = caabaac; (x^{-1})^2.x^2 = abaacabaaccaabacaaba."),
  VF("Es lo mismo el lenguaje vacío que el lenguaje que contiene solamente la palabra vacía.", false)
]);

QZ(5, 1, "Proceso de compilación", [
  VF("Las directivas de compilación en lenguaje C son líneas del código que comienzan por el símbolo «#». Son interpretadas por el preprocesador, que «prepara» o modifica el código fuente antes de ser traducido a código binario.", true),
  VF("La Tabla de Símbolos es una importante estructura de datos creada y mantenida durante el proceso de análisis y de síntesis de un compilador, con el fin de almacenar información acerca de la ocurrencia de diversas entidades, tales como nombres de variables, funciones, objetos, clases, interfaces, etc. La tabla de símbolos se utiliza en el análisis y la síntesis de un compilador.", true),
  MT("Se llama software TRADUCTOR a aquel que es capaz de convertir un texto o programa fuente escrito en un lenguaje determinado en otro texto o programa escrito en otro lenguaje distinto. Empareje cada concepto con el tipo de traductor correspondiente.", [["Son traductores de lenguajes naturales.", "TRADUCTORES DE IDIOMAS"], ["Ejecutan macroinstrucciones y directivas de compilación.", "PREPROCESADORES"], ["Traducen sentencias simples a invocaciones a programas de una biblioteca. Se utilizan especialmente en los sistemas operativos.", "INTÉRPRETES DE COMANDOS"], ["Transforman un programa fuente escrito en un lenguaje de alto nivel, obteniendo como resultado un archivo objeto con la traducción a un lenguaje de bajo nivel.", "COMPILADORES"], ["Traducen sentencia por sentencia un programa escrito en un lenguaje de alto nivel y la van ejecutando, sin crear un fichero objeto.", "INTÉRPRETES"], ["Traducen un programa fuente escrito en un lenguaje de alto nivel a otro lenguaje de programación de alto nivel.", "TRANSPILADORES"], ["Traducen un programa fuente de alto nivel obteniendo un archivo objeto con un código intermedio (p. ej. Bytecode), que posteriormente es interpretado por un motor de ejecución.", "PSEUDO-INTÉRPRETES"], ["Traductor sencillo que permite la traducción de cada sentencia fuente a una única instrucción en código máquina. El lenguaje fuente se suele llamar Lenguaje Simbólico, ya que usa nemotécnicos.", "ENSAMBLADORES"]]),
  MT("Emparejar los conceptos que se correspondan, teniendo en cuenta las fases de compilación.", [["Verificación semántica", "ANÁLISIS"], ["Generación de código de máquina", "SÍNTESIS"], ["Parser", "ANÁLISIS"], ["Generación de código intermedio", "SÍNTESIS"], ["Optimización de código intermedio", "SÍNTESIS"], ["Scanner", "ANÁLISIS"]], ["ANÁLISIS", "SÍNTESIS"]),
  VF("El enlazador o linker genera un archivo ejecutable a partir de un solo archivo objeto.", false),
  MT("Dado el siguiente programa en lenguaje C, empareje el número de línea con el error correspondiente o indique que no hay error:<pre class=\"qpre\"> 1. #include &lt;stdio.h\n 2. int main(voed)\n 3. {float sum;\n 4. int a;\n 5. f0r (a=1 ; a&lt;20 ; a++)\n 6. {\n 7. sum += a%5 / 3.5;\n 8. }\n 9. printf(\"Resultado = %s\",sum);\n10. system(\"pause\");\n11. return 0\n12. }</pre>", [["Línea 1", "Error Sintáctico"], ["Línea 2", "Error Léxico"], ["Línea 3", "Sin Error"], ["Línea 4", "Sin Error"], ["Línea 5", "Error Léxico"], ["Línea 6", "Sin Error"], ["Línea 7", "Error Semántico"], ["Línea 8", "Sin Error"], ["Línea 9", "Error Semántico"], ["Línea 10", "Error Semántico"], ["Línea 11", "Error Sintáctico"], ["Línea 12", "Sin Error"]], ["Error Léxico", "Error Sintáctico", "Error Semántico", "Sin Error"]),
  VF("La fase de optimización de código independiente de la máquina trata de mejorar el análisis léxico, de manera que se produzca un mejor código destino. Por lo general, mejor significa un código más corto.", false, "La optimización trata de mejorar el código intermedio para producir un mejor código destino; mejor significa más rápido."),
  MT("Teniendo en cuenta las fases que se llevan a cabo durante el proceso de compilación, emparejar los conceptos con dichos pasos.", [["Se revisa la estructura de la sentencia. Se convierte la expresión a notación prefija, para facilitar su posterior interpretación. Normalmente se representa con un árbol.", "PARSER"], ["Se controla la coherencia de la sentencia en el contexto del programa. Realiza la conversión de tipo necesaria. También se representa con un árbol.", "ANÁLISIS SEMÁNTICO"], ["Convierte cada código intermedio en el código ensamblador de acuerdo al procesador de que se trate.", "GENERADOR DE CÓDIGO"], ["Se reconoce cada componente léxico. Se representa cada identificador de variable y cada constante en una fila de la tabla de símbolos, guardando información relacionada a cada uno, como el tipo de dato.", "SCANNER"], ["Hace un recorrido del código intermedio eliminando instrucciones que se pueden simplificar o que son redundantes. Hace efectiva la conversión de tipos planteada en la etapa anterior.", "OPTIMIZADOR DE CÓDIGO"], ["Se genera a partir del árbol semántico, para facilitar la traducción a distintos códigos de bajo nivel. Uno de los más usados es el que utiliza 3 direcciones de memoria, una o dos para los operandos y otra para el resultado.", "GENERADOR DE CÓDIGO INTERMEDIO"]]),
  MT("Teniendo en cuenta cómo se opera la consola de comandos del sistema operativo, y en particular los distintos switches del comando gcc, emparejar según corresponda.", [["Indica el nombre del archivo de salida, cualesquiera sean las etapas cumplidas.", "-o"], ["Redirecciona la salida estándar de errores del comando o programa al archivo especificado.", "2&gt;"], ["Redirecciona la salida estándar de resultados del comando o programa al archivo especificado.", "1&gt;"], ["Realiza solamente el preprocesamiento, enviando el resultado a la salida estándar.", "-E"], ["Realiza el preprocesamiento y la traducción del programa fuente a lenguaje simbólico o ensamblador.", "-S"], ["Realiza preprocesamiento y compilación, obteniendo el archivo en código objeto; no realiza el enlazado.", "-c"], ["Muestra todos los mensajes de error y advertencia (warning) del compilador, incluso algunos cuestionables pero fáciles de evitar escribiendo el código con cuidado.", "-Wall"]]),
  VF("El cargador o loader es la parte del sistema operativo cuya función es cargar el contenido de los archivos ejecutables en la memoria RAM, asignando a cada segmento de estos archivos las direcciones de memoria base correspondientes.", true)
]);

QZ(6, 1, "Operaciones con lenguajes y Jerarquía de Chomsky", [
  MT("Dadas las siguientes gramáticas para estructura de frases, emparejar con los tipos correspondientes según la Jerarquía de Chomsky:", [["S → aSB | aB ; aB → Ba ; SB → S ; B → b", "0"], ["S → XY ; X → aX | a ; Y → bY | b", "2"], ["S → aSB | a ; aB → Ba ; B → b", "1"], ["S → aS | aX ; X → bX | b", "3"], ["S → Sb | X ; X → Xa | λ", "3"], ["S → aS | Sb | ab", "2"], ["S → aSb | aS | a", "2"], ["S → aSB ; SB → λ ; B → b", "0"], ["S → aS | bS | λ", "3"], ["S → aX | a ; X → Sb", "2"], ["S → aSb | ab", "2"]], ["0", "1", "2", "3"], "Se toma el tipo más restrictivo que cumplen todas las reglas. SB → λ y SB → S son compresoras (tipo 0). S → aS | Sb mezcla lineal por derecha y por izquierda (tipo 2)."),
  MT("Dados los siguientes lenguajes sobre el alfabeto {a, b}: L1 = { w / |w| es par pero no múltiplo de tres }, L2 = { w / |w| es impar }, emparejar con la o las expresiones que los representan, suponiendo L = {a, b}:", [["L.(L^2)*", "L2"], ["(L^2)* ∪ (L^3)*", "Otro lenguaje"], ["(L^2)*.(L^3)*", "Otro lenguaje"], ["L* − (L^2)*", "L2"], ["(L^2)* ∩ (L^3)*", "Otro lenguaje"], ["(L^2)* − (L^3)*", "L1"], ["~((L^3)*) ∩ (L^2)*", "L1"], ["~((L^2)*)", "L2"], ["(L^2)^+.L", "Otro lenguaje"]], ["L1", "L2", "Otro lenguaje"]),
  XX("Indicar la/s gramática/s que genere/n el lenguaje de todas las secuencias posibles sobre el alfabeto Σ = {a, b} que tengan longitud impar.", ["S → abS | a", "S → aaaS | aabS | abaS | abbS | baaS | babS | bbaS | bbbS | λ", "S → aX | bX | a | b ; X → aS | bS", "S → abS | baS | a | b", "S → aaS | abS | baS | bbS | a"], [2]),
  XX("Indicar la/s gramática/s que genere/n el lenguaje que incluya todas las cadenas posibles sobre el alfabeto Σ = {a, b} que contengan al menos dos «a» consecutivas.", ["S → aS | bS | aaS | λ", "S → aX | bS ; X → aY | bS ; Y → aY | bY | λ", "S → abS | bS | aaX ; X → aX | bX | λ", "S → aS | bS | aa", "S → aaX ; X → aX | bX | λ", "S → aS | bS | aaX | λ ; X → aX | bX | a | b"], [1, 2]),
  MT("Dadas las siguientes gramáticas para estructura de frases, emparejar con los lenguajes formales correspondientes.", [["S → aSb | aS | a", "a^n b^m / m ≥ 0, n &gt; m"], ["S → aS | bS | λ", "{a, b}*"], ["S → aSB ; SB → λ ; B → b", "a^{n+1} b^n / n ≥ 0"], ["S → XY ; X → aX | a ; Y → bY | b", "a^n b^m / n,m &gt; 0"], ["S → aS | Sb | ab", "a^n b^m / n,m &gt; 0"], ["S → Sb | X ; X → Xa | λ", "a^n b^m / n,m ≥ 0"], ["S → aS | aX ; X → bX | b", "a^n b^m / n,m &gt; 0"], ["S → aSB | aB ; aB → Ba ; SB → S ; B → b", "|w|_{a} ≥ |w|_{b}"], ["S → aX | a ; X → Sb", "a^{n+1} b^n / n ≥ 0"], ["S → aSB | a ; aB → Ba ; B → b", "|w|_{a} = |w|_{b} + 1"], ["S → aSb | ab", "a^n b^n / n &gt; 0"]], ["a^n b^m / m ≥ 0, n &gt; m", "{a, b}*", "a^{n+1} b^n / n ≥ 0", "a^n b^m / n,m &gt; 0", "a^n b^m / n,m ≥ 0", "|w|_{a} ≥ |w|_{b}", "|w|_{a} = |w|_{b} + 1", "a^n b^n / n &gt; 0"], "Respuestas tal como las dio la cátedra.")
]);

QZ(7, 1, "Operaciones con palabras (Haskell)", [
  XX("Dado que un lenguaje se representa con una lista en Haskell, seleccionar las condiciones que debe cumplir dicha lista.", ["Sus elementos deben ser de tipo String.", "No debe contener ningún String vacío.", "No debe tener elementos repetidos.", "No puede ser una lista vacía."], [0, 2]),
  XX("Dada la operación Producto Cartesiano de dos lenguajes, seleccionar las opciones que sean correctas.", ["No puede resolverse con lista por comprensión.", "El resultado es de tipo lista de tuplas: [(String,String)]", "El resultado es de tipo lista de listas: [[String]]", "Puede resolverse con recursividad.", "El resultado es otro lenguaje."], [1, 3]),
  VF("Dado que un lenguaje se representa en Haskell con una lista de palabras, el operador Haskell ++ actúa sobre dos listas obteniendo como resultado otra lista con los elementos de la primera seguidos de los elementos de la segunda; entonces el resultado puede interpretarse como la UNIÓN de los lenguajes que representan cada una de las listas.", false, "++ no elimina repetidos: la lista resultante puede no representar un lenguaje."),
  MT("Dada la implementación de las operaciones con lenguajes en Haskell, elegir la interpretación de [ ] que corresponda.", [["inversaPalabra [ ]", "[ ] representa la palabra vacía"], ["pertenece [ ] [ ]", "La primera [ ] representa la palabra vacía y la segunda [ ] representa un lenguaje vacío"], ["inversaLenguaje [ ]", "[ ] representa el lenguaje vacío"], ["longitud [ ]", "[ ] representa la palabra vacía"]]),
  XX("Teniendo en cuenta las operaciones sobre lenguajes Producto Cartesiano y Concatenación, analizar los siguientes enunciados y seleccionar el o los que sean verdaderos.", ["Los resultados de las dos operaciones tienen distinta cardinalidad.", "Ambas operaciones dan como resultado un conjunto.", "Ambas operaciones dan como resultado un lenguaje.", "El algoritmo para ambas operaciones es el mismo, excepto que en el producto cartesiano se construyen pares ordenados de palabras y en la concatenación se realizan concatenaciones de palabras."], [1, 3]),
  XX("Dadas las definiciones de las operaciones Estrella de Kleene y Estrella Positiva, seleccionar la o las opciones correctas.", ["L^+ = L* − {λ}", "(L*)^{-1} = (L^{-1})*", "L* = {λ} ∪ L^+", "Φ* = Φ", "L* = L^0 ∪ L^+", "Φ* = {λ}", "L* = L^+ cuando el lenguaje L no contiene la palabra vacía.", "(L^+)^{-1} ≠ (L^{-1})^+"], [1, 2, 4, 5]),
  XX("Dado el siguiente código Haskell, correspondiente a la operación de potencia de un lenguaje, seleccionar las opciones correctas:<pre class=\"qpre\">potenciaLenguajes :: [String]->Int->[String]\npotenciaLenguajes x 0 = [\"\"]\npotenciaLenguajes x 1 = x\npotenciaLenguajes x p = concatenarLenguajes x (potenciaLenguajes x (p-1))</pre>", ["potenciaLenguajes x 0 = [\"\"] es un caso particular pero no es caso base de la recursión.", "Si se elimina la línea potenciaLenguajes x 1 = x, el programa no funcionará correctamente.", "potenciaLenguajes x 1 = x es el caso base de la recursión.", "Si se elimina la línea potenciaLenguajes x 1 = x, el programa sigue funcionando correctamente pero disminuye su eficiencia.", "Si se elimina la línea potenciaLenguajes x 0 = [\"\"], el programa sigue obteniendo el resultado correcto pero es menos eficiente."], [0, 2, 3])
]);

QZ(9, 2, "GR y LR", [
  VF("El literal alfanumérico \"%30s\" empleado en una función printf puede ser generado a partir de una GR.", true),
  MC("Para obtener la GR estándar, ¿cuándo es necesario que se agregue un axioma nuevo S1 y las reglas S1 → S | λ?", ["La GR genera λ.", "El axioma figura a la derecha de alguna regla.", "La GR genera λ y el axioma figura a la derecha de alguna regla.", "La GR tiene una regla de borrado sobre el axioma."], 2),
  VF("En GR estándar la única regla compresora admitida es S → λ, cuando S no figura a la derecha de ninguna regla.", true),
  MC("Las Gramáticas Regulares sirven para describir:", ["el nivel semántico de un lenguaje.", "el nivel sintáctico de un lenguaje.", "el nivel lexicográfico de un lenguaje.", "el nivel pragmático de un lenguaje."], 2),
  VF("Las GR tienen la capacidad de generar solo Lenguajes Regulares.", true),
  MC("El formato estándar de una GR por la derecha puede tener los siguientes tipos de reglas:", ["N1 → tN2, N → λ", "N1 → tN2, N → t, S → λ pero S no figura a la derecha.", "N1 → N2, N → t", "N1 → tN2, N → t, S → λ"], 1),
  MT("Pasos a seguir para obtener el Formato Estándar de Chomsky tipo 3:<br>1.- Eliminar reglas …<br>2.- Eliminar el … de la derecha, si es que λ pertenece a la GR.<br>3.- Eliminar reglas de …<br>4.- Eliminar reglas de …<br>5.- Realizar las sustituciones necesarias para reducir a uno la longitud de las secuencias de … que hubiera en las reglas.", [["1.- Eliminar reglas…", "innecesarias", ["innecesarias", "recursivas", "unitarias"]], ["2.- Eliminar el … de la derecha", "axioma", ["axioma", "último terminal", "no terminal"]], ["3.- Eliminar reglas de…", "redenominación", ["redenominación", "borrado", "producción"]], ["4.- Eliminar reglas de…", "borrado", ["redenominación", "borrado", "producción"]], ["5.- … secuencias de…", "terminales", ["terminales", "no terminales", "reglas"]]], null, "En el intento se escribió «axioma S» y fue marcado incorrecto: la respuesta esperada era «axioma»."),
  XX("Indicar cuáles de las siguientes son características de los lenguajes regulares.", ["Cualquier lenguaje finito es regular.", "Cuando se tiene que limitar la longitud de sus palabras es necesario utilizar la operación de intersección.", "Los lenguajes regulares son todos infinitos.", "Pueden ser generados por Gramáticas de tipo 2 o Libres del Contexto.", "Solamente pueden ser generados por Gramáticas Regulares.", "Para representarlos es suficiente utilizar las operaciones de lenguajes: Concatenación, Unión y Estrella de Kleene."], [0, 3, 5])
]);

QZ(10, 2, "GR y LR · Práctica", [
  MT("Dadas las siguientes GR:<br><b>GR1:</b> S → abX | aT | bY | cZ ; X → aX | bW | ca | λ ; Y → bY | Z | b | λ ; Z → bbY | c<br><b>GR2:</b> S → abS | bbS | aZ | baY | ab | bb ; Y → baY | bbS<br>Emparejar con las FNC3 correspondientes:<br><b>FNC3-A:</b> S → aA | bA | bC | aB | bB ; Y → bC | bA ; A → bS ; B → b ; C → aY<br><b>FNC3-B:</b> S → aD | bY | cZ | aB | b ; X → aX | cA | a ; Y → bY | b | bC | bA | c ; Z → bE | c | bB ; A → a ; B → b ; C → c ; D → bY ; E → cX<br><b>FNC3-C:</b> S → aE | bY | cZ | aB | b ; X → aX | cA | a ; Y → bY | b | bD | bB | c ; Z → bD | c | bB ; A → a ; B → b ; C → c ; D → bY ; E → bX<br><b>FNC3-D:</b> S → aE | bB | cC | aB | b ; A → aA | cA | a ; B → bB | b | bD | bB | c ; C → bD | c | bB ; D → bB | bA", [["GR1", "FNC3-C"], ["GR2", "FNC3-A"]], ["FNC3-A", "FNC3-B", "FNC3-C", "FNC3-D"]),
  MT("Dadas las siguientes GR, emparejar con los LR que generan:", [["S → X | aS ; X → aS | bX | b", "{b}.{a, b}*"], ["S → aX | bY | a | b | λ ; X → aX | bY | a | b ; Y → bY | b", "(a^n).(b^m) / n ≥ 0, m ≥ 0"], ["S → aX | bS | λ ; X → aS | bX", "w ∈ {a, b}* y |w|_{a} par"], ["S → aS | bX ; X → bX | b", "(a^n).(b^m) / n ≥ 0, m ≥ 2"], ["S → aS | bX | b ; X → aX | bS", "w ∈ {b}.{a, b}* y |w|_{b} impar"]], null, "Etiquetas tal como las puso la cátedra. Ojo: la primera y la última gramáticas generan palabras que terminan en b; en la notación del quiz eso quedó escrito como {b}.{a, b}*."),
  MT("Dadas las siguientes GR, decir si están en la FNC3.", [["S → aS | bX | b ; X → aX | bS", "SI"], ["S → X | aS ; X → aS | bX | b", "NO"], ["S → aX | bS | λ ; X → aS | bX", "NO"], ["S → aS | bX ; X → bX | b", "SI"], ["S → aX | bY | a | b | λ ; X → aX | bY | a | b ; Y → bY | b", "SI"]], ["SI", "NO"], "La segunda tiene una regla unitaria (S → X). La tercera tiene S → λ con S a la derecha.")
]);

