QZ(12, 2, "ER y GR · Práctica", [
  VF("Se puede afirmar que: (a+b)* + Ø = (a+b)*", true),
  VF("Se puede afirmar que: a*.(b + a.a) = a*.b + a*.a.a", true),
  VF("Se puede afirmar que: a.(a.b+b.a)* = a.(a.b)* + a.(b.a)*", false),
  MC("Dada la siguiente GR: S → aS | bX ; X → bY | a ; Y → aX, seleccionar la ER correspondiente.", ["a*b (ba*a)*", "a* + b.b.a* + a", "a*b.b(a.a)*", "(a*.b).(b.a)*.a", "a*.b + b.a*.a"], 3),
  MC("Todas las secuencias de longitud impar sobre Σ = {a, b}:", ["a.((a+b).(a+b))*", "((a+b).(a+b))*.a", "(a+b).(a.a+a.b+b.a+b.b)*", "(a.b+b.a)*.(a+b)"], 2),
  MC("Dadas las siguientes ER: a + b + (a.b)* ; b + a.(a.b)*.(a+λ) ; (b+λ).(a+a.b)* ; (λ+a).(a.a+b.a)*.(λ+b) ; λ + a.(a+b*.a.b*)* — ¿cuántas incluyen a λ entre las palabras que representan?", ["Cuatro ER", "Una sola ER", "Todas estas ER", "Tres ER", "Dos ER"], 0),
  VF("Se puede afirmar que: (a+b)*.Ø = (a+b)*", false, "Concatenar con el vacío da el vacío."),
  XX("Todas las secuencias que no tienen a consecutivas sobre Σ = {a, b}:", ["(b.a.b+b)*", "(b+a.b)*.(a+λ)", "(b+a.b)* + (b.a+b)*.b", "(a+λ).(b+b.a)*"], [1, 2, 3]),
  MC("Las palabras baaa y aaab están incluidas en…", ["a*.b.(b.a*.a)* + b.a.a", "b*.a.(a.a)* + a.a + a.b", "b.a*.(a.b*)*", "a*.b + (b.a)*.b.a*.a", "a* + b*.b.a* + a.(a.a)*.b"], 3),
  MC("Todas las secuencias que no tienen b consecutivas sobre Σ = {a, b}:", ["(a+b.a)*.(b+λ)", "(a+b.a)*", "(a+b.a)*.(a+b)", "(a+a.b)*"], 0),
  MC("La Expresión Regular a.(a.a+b.a+a.b+b.b)* representa a todas las secuencias sobre {a, b}…", ["de longitud impar que empiezan con a", "de longitud impar que empiezan con a y terminan con b", "de longitud impar", "que empiezan con a", "sin restricciones", "que comienzan con a, más λ."], 0),
  MC("La Expresión Regular (a+ab)* representa todas las secuencias sobre {a, b}…", ["que comienzan con a y no tienen b consecutivas, más λ.", "que no tienen b consecutivas", "que comienzan con a y terminan con b, más λ.", "que comienzan con a y no tienen b consecutivas"], 0)
]);

QZ(13, 2, "MEF", [
  MT("Una Máquina Secuencial o Máquina de Estados Finitos (MEF) es un … matemático, que en general sirve para diseñar el … de un sistema. El objetivo del modelo es obtener una secuencia de … de igual longitud y en correspondencia con una secuencia de …, pero que no depende solo de esta última sino del estado en el que se encuentre el modelo.", [["es un…", "modelo", ["modelo", "lenguaje", "programa"]], ["diseñar el…", "comportamiento", ["comportamiento", "hardware", "código"]], ["secuencia de… (1)", "salida", ["salida", "entrada", "estados"]], ["secuencia de… (2)", "entrada", ["salida", "entrada", "estados"]]]),
  MT("En general el modelo de MEF puede estar en cualquiera de sus estados cuando comienza a funcionar y realiza las siguientes acciones: 1) … un símbolo de la cinta de entrada y mueve el cabezal de lectura a la …; 2) de acuerdo al … y al símbolo leído, transiciona a un … (que puede ser el mismo); 3) ESCRIBE un símbolo en la cinta de salida y mueve el cabezal de escritura a la …. Para seleccionar el símbolo que escribe existen dos criterios equivalentes: … elige el símbolo según el estado actual y el símbolo leído; … elige el símbolo de acuerdo al estado nuevo al que transiciona. 4) Repite hasta que lee totalmente la palabra y se detiene.", [["1)", "Lee", ["Lee", "Escribe", "Borra"]], ["mueve el cabezal de lectura a la…", "Derecha", ["Derecha", "Izquierda"]], ["2) de acuerdo al…", "Estado Actual", ["Estado Actual", "Estado Inicial", "Estado Final"]], ["transiciona a un…", "Nuevo Estado", ["Nuevo Estado", "Estado Final", "Estado Inicial"]], ["mueve el cabezal de escritura a la…", "Derecha", ["Derecha", "Izquierda"]], ["según el estado actual y el símbolo leído:", "Mealy", ["Mealy", "Moore"]], ["según el estado nuevo:", "Moore", ["Mealy", "Moore"]]]),
  VF("En el modelo de Mealy la salida es instantánea y depende solo del estado actual.", false, "Depende del estado actual y del símbolo leído."),
  VF("En el modelo de Moore la salida sufre un retardo, ya que se debe realizar primero la transición a otro estado, según el símbolo leído y el estado actual, para recién escribir un símbolo en la cinta de salida, que depende solo del estado nuevo.", true),
  VF("El equivalente Mealy de una MEF Moore puede tener menos estados.", true),
  VF("Un estado generador en un modelo de Moore no tiene salida asociada.", true),
  VF("El reconocimiento o aceptación de Lenguajes Regulares es un problema cuya solución se puede modelizar con una MEF, resultando más apropiado el modelo de Moore.", true),
  VF("En una MEF de Mealy la salida sufre un retardo, ya que se debe realizar primero la transición a otro estado, según el símbolo leído y el estado actual, para recién escribir un símbolo en la cinta de salida, que depende solo del estado al que se ha transicionado.", false),
  VF("Una MEF tipo Moore puede tener menos estados que su equivalente Mealy.", false)
]);

